nextflow_process {

    name "Test Process SENTIEON_RSEMPREPAREREFERENCE"
    script "../main.nf"
    process "SENTIEON_RSEMPREPAREREFERENCE"
    tag "modules"
    tag "modules_nfcore"
    tag "sentieon"
    tag "sentieon/rsempreparereference"

    test("homo_sapiens") {

        when {
            process {
                """
                input[0] = Channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true))
                input[1] = Channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true))
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    process.out.index,
                    process.out.transcript_fasta,
                    process.out.findAll { key, val -> key.startsWith("versions") }
                ).match() }
            )
        }
    }

    test("homo_sapiens - stub") {

    options "-stub"

        when {
            process {
                """
                input[0] = Channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.fasta', checkIfExists: true))
                input[1] = Channel.of(file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/genome.gtf', checkIfExists: true))
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(process.out).match() }
            )
        }
    }
}

env {
    // NOTE This is how pipeline users will use Sentieon in real world use
    // TODO: Update to `env('SENTIEON_LICSRVR_IP')` when minimum Nextflow version is >= 26.04.0
    SENTIEON_LICENSE = env('SENTIEON_LICSRVR_IP')
    // NOTE This should only happen in GitHub actions or nf-core MegaTests
    // TODO: Update to `env('SENTIEON_AUTH_MECH')` when minimum Nextflow version is >= 26.04.0
    SENTIEON_AUTH_MECH = env('SENTIEON_AUTH_MECH')
    SENTIEON_AUTH_DATA = secrets.SENTIEON_AUTH_DATA
    // NOTE This is how pipeline users will test out Sentieon with a license file
    // nextflow secrets set SENTIEON_LICENSE_BASE64 \$(cat <sentieon_license_file.lic> | base64 -w 0)
}
